CREATE TABLE admin.position (id UUID PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name_ro VARCHAR(255) NOT NULL, name_en VARCHAR(255), module VARCHAR(64), default_role_ids UUID[] NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE admin.employee (id UUID PRIMARY KEY, employee_no VARCHAR(64) NOT NULL UNIQUE, first_name VARCHAR(255) NOT NULL, last_name VARCHAR(255) NOT NULL, cnp_hash VARCHAR(64), phone VARCHAR(64), email VARCHAR(255), hire_date DATE NOT NULL, termination_date DATE, status VARCHAR(32) NOT NULL, position_id UUID, home_site_id UUID, home_site_type VARCHAR(64), user_id UUID, photo_url TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX uq_employee_user_id ON admin.employee(user_id) WHERE user_id IS NOT NULL;
CREATE INDEX idx_employee_site_status ON admin.employee(home_site_id, status);
CREATE TABLE admin.team (id UUID PRIMARY KEY, site_id UUID NOT NULL, name VARCHAR(255) NOT NULL, leader_employee_id UUID, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_team_site ON admin.team(site_id);
CREATE TABLE admin.team_member (id UUID PRIMARY KEY, team_id UUID NOT NULL, employee_id UUID NOT NULL, from_date DATE NOT NULL, to_date DATE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_team_member_team ON admin.team_member(team_id);
CREATE INDEX idx_team_member_employee ON admin.team_member(employee_id);
CREATE TABLE admin.shift_template (id UUID PRIMARY KEY, site_id UUID, code VARCHAR(64) NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, break_minutes INTEGER NOT NULL DEFAULT 0, color VARCHAR(32), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX uq_shift_template_site_code ON admin.shift_template(site_id, code);
CREATE TABLE admin.roster (id UUID PRIMARY KEY, site_id UUID NOT NULL, week_start DATE NOT NULL, status VARCHAR(32) NOT NULL, published_by UUID, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0, UNIQUE(site_id, week_start));
CREATE INDEX idx_roster_site_week ON admin.roster(site_id, week_start);
CREATE TABLE admin.duty_assignment (id UUID PRIMARY KEY, roster_id UUID NOT NULL, employee_id UUID NOT NULL, date DATE NOT NULL, shift_template_id UUID NOT NULL, sub_unit_id UUID, role_hint VARCHAR(255), note TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0, UNIQUE(roster_id, employee_id, date, shift_template_id));
CREATE INDEX idx_duty_assignment_roster ON admin.duty_assignment(roster_id);
CREATE TABLE admin.absence (id UUID PRIMARY KEY, employee_id UUID NOT NULL, from_date DATE NOT NULL, to_date DATE NOT NULL, type VARCHAR(32) NOT NULL, approved_by UUID, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_absence_employee_dates ON admin.absence(employee_id, from_date, to_date);
CREATE TABLE admin.certification (id UUID PRIMARY KEY, employee_id UUID NOT NULL, type VARCHAR(64) NOT NULL, number VARCHAR(255), issued_at DATE, expires_at DATE, document_ref TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, created_by UUID, updated_by UUID, version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_certification_employee ON admin.certification(employee_id);
CREATE INDEX idx_certification_expiry ON admin.certification(expires_at);
